def describe_infinite_engineering_intelligence() -> str:
    lines = [
        "TitanAI Infinite Engineering Intelligence Era",
        "",
        "This era focuses on TitanAI moving from a software engineering ecosystem into a permanent digital technology organization.",
        "",
    ]
    for capability in INFINITE_ENGINEERING_CAPABILITIES:
        lines.append(f"- {capability.version} {capability.name} [{capability.category}]")
        lines.append(f"  {capability.purpose}")
    return "\n".join(lines)
